function converted(raw, dpr, scale=1) {
  const match=/^(-?[\d.]+)(dip|dp|sp|px)$/.exec(raw);
  if(!match) return null;
  return Math.round(Number(match[1])*(match[2]==='px'?1:dpr)*(match[2]==='sp'?scale:1))/dpr;
}
test('all279 native fixture inputs resolve; selected scalar outputs retain qualified evidence',()=>{
  assert.equal(RESEARCH_CASES.length,279);
  for(const [id,config,q,expected] of RESEARCH_CASES){
    const dpr=q.density/160;
    const result=resolveLayout(config,{width:q.width,height:q.height,dpr,fontScale:q.font_scale,configuration:q});
    for(const region of ['art','title','secondary','wave','transport','subart','navbar','mini']){
      for(const property of ['x','y','width','height']) assert.ok(Number.isFinite(result[region][property]),`${id} ${region}.${property}`);
      assert.ok(result[region].width>=0&&result[region].height>=0,`${id} nonnegative ${region}`);
    }
    assert.equal(result.navbar.height,converted(expected.navbarHeight,dpr),`${id} qualified navbar height`);
    assert.equal(result.title.fontSize,converted(expected.titleSize,dpr,q.font_scale),`${id} font size`);
    if(expected.artReserve)assert.equal(result.effective.artReserve,converted(expected.artReserve,dpr,q.font_scale),`${id} reserved art space`);
    if(expected.artPadding)assert.equal(result.effective.artPadding,converted(expected.artPadding,dpr,q.font_scale),`${id} art padding`);
    // Raw radius retained by graphics: returned radius additionally follows .975/1 view scale.
    assert.ok(Math.abs(result.art.radius/result.art.scale-Number.parseFloat(expected.artRadius))<.01,`${id} artwork radius`);
  }
});
test('native Default item equations retain insets and native-pixel rounding',()=>{
  const r=resolveLayout({}, {width:360,height:640,dpr:2,insets:{top:24,bottom:24},insetsAreEffective:true}, {playing:true});
  assert.deepEqual(r.art.frame,{x:8,y:32,width:344,height:344});
  assert.equal(r.item.y,24);assert.equal(r.item.artSide,360);
  assert.equal(r.navbar.reference,56);
  assert.equal(r.mini.totalReference,130);
  assert.equal(r.art.scale,1);
});
test('bottom inset reduction only applies inside the native threshold interval',()=>{
  const effective=bottom=>resolveLayout({}, {width:360,height:780,dpr:2,insets:{bottom}}).effective.insets.bottom;
  assert.equal(effective(2),2);assert.equal(effective(24),20);assert.equal(effective(26),26);
});
test('portrait layout and landscape ownership change structurally',()=>{
  const v={width:360,height:780,dpr:2};
  const a=resolveLayout({alt_layout:'Default'},v), b=resolveLayout({alt_layout:'Alternative'},v),c=resolveLayout({alt_layout:'FullCover'},v);
  assert.ok(a.title.y<a.art.frame.y+a.art.frame.height);
  assert.ok(b.title.y>=b.art.frame.y+b.art.frame.height);
  assert.ok(c.rating.y>c.secondary.y);
  const l=resolveLayout({alt_layout:'FullCover'},{width:780,height:360,dpr:2});
  assert.ok(l.title.x>=l.art.frame.x+l.art.frame.width);
  assert.ok(l.wave.x>=l.art.frame.x+l.art.frame.width);
});
test('more buttons and waveform modes remain independent; plain installs transport',()=>{
  const v={width:430,height:932,dpr:3};
  const a=resolveLayout({more_buttons:false,seekbar:'scrolling'},v),b=resolveLayout({more_buttons:true,seekbar:'scrolling'},v);
  assert.equal(a.wave.bars,100);assert.equal(b.wave.bars,100);
  assert.equal(a.transport.buttons.previous.visible,false);assert.equal(b.transport.buttons.previous.visible,true);
  const fixed=resolveLayout({seekbar:'static'},v), plain=resolveLayout({seekbar:'plain',more_buttons:false},v);
  assert.equal(fixed.wave.bars,60);assert.equal(plain.wave.visible,false);assert.equal(plain.plainSeek.visible,true);
  assert.equal(plain.transport.buttons.previous.visible,true);
  assert.equal(resolveLayout({playing:true,more_buttons:false},v).transport.height,25);
});
test('metric kernel is Z-trimmed and exposes absent metrics without pretending to know them',()=>{
  assert.deepEqual(textMetricKernel({zTop:-14,zBottom:1,width:52.2}),{width:53,height:15,baseline:14});
  const measured=resolveLayout({}, {width:360,height:780,dpr:2,textMetrics:{title:{zTop:-14,zBottom:1,width:52.2}}});
  assert.equal(measured.title.height,15);assert.equal(measured.title.metricSource,'caller');
  assert.equal(resolveLayout({}, {width:360,height:780}).title.metricSource,'browser-em-fallback');
});
test('sub-art state preserves gaps and right-hand slot ordering',()=>{
  const r=resolveLayout({subaa:['vis','sleep','none','shuffle','repeat']},{width:360,height:780,dpr:2});
  assert.equal(r.subart.slots[2].action,null);
  assert.ok(r.subart.slots[4].x<r.subart.slots[3].x);
  assert.equal(r.subart.slots[0].action,'visualization');
});
