test('custom foreground crop treats tall portrait sources separately',()=>{
  assert.equal(resolveArtworkCrop(100,200,300,300,1).mode,'portrait-center');
  assert.equal(resolveArtworkCrop(200,100,300,300,1).mode,'width-fit');
  assert.equal(resolveArtworkCrop(100,200,300,300,2).mode,'orientation-crop');
});

test('centerCropXY chooses source orientation; centerCrop forces width fit',()=>{
  assert.equal(resolveArtworkCrop(200,100,500,100,2).scale,1);
  assert.equal(resolveArtworkCrop(200,100,500,100,0).scale,2.5);
  assert.deepEqual(resolveArtworkCrop(100,200,300,300,1).clipRect,{x:75,y:0,width:150,height:300});
});

test('wave view fills its region; native internal padding is applied only by graphics',()=>{
  const portrait=resolveLayout({}, {width:360,height:780,dpr:2});
  assert.equal(portrait.wave.x,portrait.wave.region.x);
  assert.equal(portrait.wave.width,portrait.wave.region.width);
  assert.equal(portrait.wave.paddingX,8);
  const landscape=resolveLayout({}, {width:780,height:360,dpr:2});
  assert.equal(landscape.wave.x,landscape.wave.region.x);
  assert.equal(landscape.wave.width,landscape.wave.region.width);
  assert.equal(landscape.wave.paddingX,0);
  const plain=resolveLayout({seekbar:'plain'}, {width:360,height:780,dpr:2});
  assert.equal(plain.plainSeek.x,14);
  assert.equal(plain.plainSeek.width,332);
  assert.equal(plain.plainSeek.padding,12);
});
test('Alternative uses the independently licensed Manrope family; Bold retains an explicit fallback',()=>{
  const v={width:360,height:780,dpr:2};
  assert.equal(resolveLayout({font_variant:'Alternative'},v).title.fontFamily,'Manrope, sans-serif');
  assert.equal(resolveLayout({font_variant:'Alternative'},v).mini.title.fontFamily,'Manrope, sans-serif');
  assert.equal(resolveLayout({font_variant:'Bold'},v).title.fontFamily,'system-ui, sans-serif');
});
